function ok(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);echo "PASS $m\n";}
function reject(callable $f,string $m,string $class=InvalidArgumentException::class):void{try{$f();}catch(Throwable $e){if(!$e instanceof $class)throw $e;ok(true,$m);return;}throw new RuntimeException('Unexpected success: '.$m);}
function clean(string $p):void{if(!is_dir($p))return;foreach(new DirectoryIterator($p) as $f){if($f->isDot())continue;if($f->isDir()&&!$f->isLink())clean($f->getPathname());else unlink($f->getPathname());}rmdir($p);}
