{"openapi":"3.1.0","info":{"title":"Users API","version":"1.0","description":"Safe <script>alert(1)</script> ![image](https://evil.example/track.png)"},"servers":[{"url":"https://api.example.org/{version}","variables":{"version":{"default":"v1"}}}],"security":[{"bearer":[]}],"paths":{"/users/{id}":{"parameters":[{"$ref":"parts.json#/id"}],"get":{"operationId":"getUser","summary":"Find user","tags":["Users"],"responses":{"200":{"$ref":"parts.json#/response"},"404":{"description":"Not found"}}}},"/users":{"post":{"summary":"Create user","security":[],"requestBody":{"required":true,"content":{"application/json":{"schema":{"$ref":"#/components/schemas/User"},"example":{"name":"Example"}}}},"responses":{"201":{"description":"Created"}}}}},"components":{"securitySchemes":{"bearer":{"type":"http","scheme":"bearer"}},"schemas":{"User":{"$ref":"parts.json#/User"},"Result":{"oneOf":[{"$ref":"#/components/schemas/User"},{"type":"null"}]}}}}
JSON,false,64,JSON_THROW_ON_ERROR);$main->paths->{'/users/{id}'}->get->summary=$summary;$main->info->version=$version;if(!$extra)unset($main->paths->{'/users'});
    $parts='{"id":{"name":"id","in":"path","required":true,"schema":{"type":"string"}},"response":{"description":"Found","content":{"application/json":{"schema":{"$ref":"#/User"},"example":{"name":"Example"}}}},"User":{"type":"object","required":["name"],"properties":{"name":{"type":"string"},"parent":{"$ref":"#/User"},"status":{"type":"string","enum":["active","inactive"]}}}}';
